{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울특별시 청년 기본 조례상 시정에 반영된 청년 제안 정책의 추진 지연 시 시장에게 추진현황 점검·평가 권한이 있는지",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "시장은 시정에 반영된 청년 제안 정책 등의 추진현황을 점검하고 평가할 수 있다. 이는 추진 지연 여부와 무관하게 시장에게 부여된 재량 권한이다.",
          "b_ids": "청년:제10조제2항"
        }
      ],
      "e_status": "ANSWERED"
    },
    {
      "a_request": "R2",
      "b_asked": "서울특별시 청년정책조정위원회가 청년 제안 정책의 추진현황 점검·개선에 관하여 권고할 수 있는지",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "청년정책조정위원회는 청년 제안 정책의 추진현황 점검 및 개선에 관한 사항을 심의·조정하며, 필요한 경우 해당 사항에 대해 점검·권고할 수 있다.",
          "b_ids": "청년:제9조제2항, 청년:제9조제2항제7호"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
